// Global state
let selectedTicker = null;
let stockData = [];

// Sector colors
const sectorColors = {
    'Information Technology': '#4285F4',
    'Industry': '#EA4335',
    'Energy': '#FBBC04',
    'Financial': '#34A853',
    'ETF': '#9E9E9E'
};

// Format market cap for display
function formatMarketCap(value) {
    if (!value || isNaN(value)) return '-';
    const num = parseFloat(value);
    if (num >= 1e12) {
        return (num / 1e12).toFixed(2) + 'T';
    } else if (num >= 1e9) {
        return (num / 1e9).toFixed(2) + 'B';
    } else if (num >= 1e6) {
        return (num / 1e6).toFixed(2) + 'M';
    }
    return num.toLocaleString();
}

// Load and parse CSV data
async function loadData() {
    const response = await fetch('data/stock-descriptions.csv');
    const text = await response.text();
    const lines = text.trim().split('\n');
    const headers = lines[0].split(',');

    const data = [];
    for (let i = 1; i < lines.length; i++) {
        const line = lines[i];
        const values = parseCSVLine(line);
        if (values.length >= 5) {
            const obj = {
                ticker: values[1],
                sector: values[2],
                name: values[3],
                marketCap: parseFloat(values[4]) || null,
                country: values[7] || null,
                website: values[8] || null
            };
            data.push(obj);
        }
    }
    return data;
}

// Parse CSV line handling quoted fields
function parseCSVLine(line) {
    const result = [];
    let current = '';
    let inQuotes = false;

    for (let i = 0; i < line.length; i++) {
        const char = line[i];
        if (char === '"') {
            inQuotes = !inQuotes;
        } else if (char === ',' && !inQuotes) {
            result.push(current.trim());
            current = '';
        } else {
            current += char;
        }
    }
    result.push(current.trim());
    return result;
}

// Create bubble chart
function createBubbleChart(data) {
    const container = document.getElementById('bubble-chart');
    const width = container.clientWidth;
    const height = container.clientHeight;

    // Clear previous
    container.innerHTML = '';

    const svg = d3.select('#bubble-chart')
        .append('svg')
        .attr('width', width)
        .attr('height', height);

    // Create tooltip
    const tooltip = d3.select('#bubble-chart')
        .append('div')
        .attr('class', 'tooltip')
        .style('opacity', 0)
        .style('display', 'none');

    // Compute radius scale based on market cap
    const marketCaps = data.filter(d => d.marketCap).map(d => d.marketCap);
    const radiusScale = d3.scaleSqrt()
        .domain([d3.min(marketCaps), d3.max(marketCaps)])
        .range([15, 50]);

    const defaultRadius = 12; // For ETFs without market cap

    // Get unique sectors and their center positions
    const sectors = [...new Set(data.map(d => d.sector))];
    const sectorCenters = {};
    const numSectors = sectors.length;
    const centerX = width / 2;
    const centerY = height / 2;
    const orbitRadius = Math.min(width, height) * 0.25;

    sectors.forEach((sector, i) => {
        const angle = (2 * Math.PI * i) / numSectors - Math.PI / 2;
        sectorCenters[sector] = {
            x: centerX + orbitRadius * Math.cos(angle),
            y: centerY + orbitRadius * Math.sin(angle)
        };
    });

    // Create nodes with initial positions
    const nodes = data.map(d => ({
        ...d,
        radius: d.marketCap ? radiusScale(d.marketCap) : defaultRadius,
        x: sectorCenters[d.sector].x + (Math.random() - 0.5) * 100,
        y: sectorCenters[d.sector].y + (Math.random() - 0.5) * 100
    }));

    // Create force simulation
    const simulation = d3.forceSimulation(nodes)
        .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.3))
        .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.3))
        .force('center', d3.forceCenter(centerX, centerY).strength(0.05))
        .force('collision', d3.forceCollide(d => d.radius + 2).strength(1))
        .force('charge', d3.forceManyBody().strength(-5))
        .alphaDecay(0.02)
        .on('tick', ticked);

    // Create bubble groups
    const bubbleGroups = svg.selectAll('.bubble-group')
        .data(nodes)
        .join('g')
        .attr('class', 'bubble-group');

    // Create bubbles
    const bubbles = bubbleGroups.append('circle')
        .attr('class', 'bubble')
        .attr('r', d => d.radius)
        .attr('fill', d => sectorColors[d.sector] || '#999')
        .attr('opacity', 0.85)
        .on('mouseover', function(event, d) {
            // Only show tooltip for non-ETF stocks
            if (d.sector !== 'ETF') {
                tooltip
                    .style('display', 'block')
                    .style('opacity', 1)
                    .html(`
                        <div class="ticker">${d.ticker}</div>
                        <div class="name">${d.name}</div>
                        <div class="sector">${d.sector}</div>
                    `);
            }
        })
        .on('mousemove', function(event) {
            const d = d3.select(this).datum();
            if (d.sector !== 'ETF') {
                const rect = container.getBoundingClientRect();
                tooltip
                    .style('left', (event.clientX - rect.left + 15) + 'px')
                    .style('top', (event.clientY - rect.top - 10) + 'px');
            }
        })
        .on('mouseout', function() {
            tooltip
                .style('opacity', 0)
                .style('display', 'none');
        })
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    // Create labels
    const labels = bubbleGroups.append('text')
        .attr('class', 'bubble-label')
        .text(d => d.ticker)
        .style('font-size', d => Math.max(8, Math.min(12, d.radius / 2.5)) + 'px');

    function ticked() {
        // Keep bubbles within bounds
        nodes.forEach(d => {
            d.x = Math.max(d.radius, Math.min(width - d.radius, d.x));
            d.y = Math.max(d.radius, Math.min(height - d.radius, d.y));
        });

        bubbleGroups.attr('transform', d => `translate(${d.x}, ${d.y})`);
    }

    // Create legend
    createLegend(sectors);

    // Store reference for updates
    window.bubbles = bubbles;
    window.nodes = nodes;
}

// Create legend
function createLegend(sectors) {
    const legendContainer = document.querySelector('.legend');
    if (!legendContainer) return;

    legendContainer.innerHTML = '';

    sectors.forEach(sector => {
        const item = document.createElement('div');
        item.className = 'legend-item';

        const color = document.createElement('div');
        color.className = 'legend-color';
        color.style.backgroundColor = sectorColors[sector] || '#999';

        const label = document.createElement('span');
        label.textContent = sector;

        item.appendChild(color);
        item.appendChild(label);
        legendContainer.appendChild(item);
    });
}

// Create data table
function createTable(data) {
    const tbody = document.querySelector('#stock-table tbody');
    tbody.innerHTML = '';

    // Sort by market cap (descending), with ETFs at the end
    const sortedData = [...data].sort((a, b) => {
        if (!a.marketCap && !b.marketCap) return 0;
        if (!a.marketCap) return 1;
        if (!b.marketCap) return -1;
        return b.marketCap - a.marketCap;
    });

    sortedData.forEach(stock => {
        const row = document.createElement('tr');
        row.dataset.ticker = stock.ticker;
        row.innerHTML = `
            <td class="ticker-cell">${stock.ticker}</td>
            <td>${stock.name}</td>
            <td>${stock.sector}</td>
            <td class="market-cap-cell">${formatMarketCap(stock.marketCap)}</td>
        `;
        row.addEventListener('click', () => selectStock(stock.ticker));
        tbody.appendChild(row);
    });
}

// Select a stock (highlight in both chart and table)
function selectStock(ticker) {
    // Toggle selection
    if (selectedTicker === ticker) {
        selectedTicker = null;
    } else {
        selectedTicker = ticker;
    }

    // Update bubble chart
    if (window.bubbles) {
        window.bubbles
            .classed('selected', d => d.ticker === selectedTicker)
            .attr('stroke', d => d.ticker === selectedTicker ? '#000' : null)
            .attr('stroke-width', d => d.ticker === selectedTicker ? 3 : null);
    }

    // Update table
    const rows = document.querySelectorAll('#stock-table tbody tr');
    rows.forEach(row => {
        if (row.dataset.ticker === selectedTicker) {
            row.classList.add('selected');
            // Scroll into view
            row.scrollIntoView({ behavior: 'smooth', block: 'center' });
        } else {
            row.classList.remove('selected');
        }
    });
}

// Initialize
async function init() {
    try {
        stockData = await loadData();
        createBubbleChart(stockData);
        createTable(stockData);

        // Handle resize
        window.addEventListener('resize', () => {
            createBubbleChart(stockData);
        });
    } catch (error) {
        console.error('Error loading data:', error);
    }
}

// Start when DOM is ready
document.addEventListener('DOMContentLoaded', init);

