        bubbleGroups.attr('transform', d => `translate(${d.x}, ${d.y})`);
    }

    // Create legend
    createLegend(sectors);

    // Store reference for updates
    window.bubbles = bubbles;
    window.nodes = nodes;
}

// Create legend
function createLegend(sectors) {
    const legendContainer = document.querySelector('.legend');
    if (!legendContainer) return;

    legendContainer.innerHTML = '';

    sectors.forEach(sector => {
        const item = document.createElement('div');
        item.className = 'legend-item';

        const color = document.createElement('div');
        color.className = 'legend-color';
        color.style.backgroundColor = sectorColors[sector] || '#999';

        const label = document.createElement('span');
        label.textContent = sector;

        item.appendChild(color);
        item.appendChild(label);
        legendContainer.appendChild(item);
    });
}

// Create data table
function createTable(data) {
    const tbody = document.querySelector('#stock-table tbody');
    tbody.innerHTML = '';

    // Sort by market cap (descending), with ETFs at the end
    const sortedData = [...data].sort((a, b) => {
        if (!a.marketCap && !b.marketCap) return 0;
        if (!a.marketCap) return 1;
        if (!b.marketCap) return -1;
        return b.marketCap - a.marketCap;
    });

    sortedData.forEach(stock => {
        const row = document.createElement('tr');
        row.dataset.ticker = stock.ticker;
        row.innerHTML = `
            <td class="ticker-cell">${stock.ticker}</td>
            <td>${stock.name}</td>
            <td>${stock.sector}</td>
            <td class="market-cap-cell">${formatMarketCap(stock.marketCap)}</td>
        `;
        row.addEventListener('click', () => selectStock(stock.ticker));
        tbody.appendChild(row);
    });
}

// Select a stock (highlight in both chart and table)
function selectStock(ticker) {
    // Toggle selection
    if (selectedTicker === ticker) {
        selectedTicker = null;
    } else {
        selectedTicker = ticker;
    }

    // Update bubble chart
    if (window.bubbles) {
        window.bubbles
            .classed('selected', d => d.ticker === selectedTicker)
            .attr('stroke', d => d.ticker === selectedTicker ? '#000' : null)
            .attr('stroke-width', d => d.ticker === selectedTicker ? 3 : null);
    }

    // Update table
    const rows = document.querySelectorAll('#stock-table tbody tr');
    rows.forEach(row => {
        if (row.dataset.ticker === selectedTicker) {
            row.classList.add('selected');
            // Scroll into view
            row.scrollIntoView({ behavior: 'smooth', block: 'center' });
        } else {
            row.classList.remove('selected');
        }
    });
}

// Initialize
async function init() {
    try {
        stockData = await loadData();
        createBubbleChart(stockData);
        createTable(stockData);

        // Handle resize
        window.addEventListener('resize', () => {
            createBubbleChart(stockData);
        });
    } catch (error) {
        console.error('Error loading data:', error);
    }
}

// Start when DOM is ready
document.addEventListener('DOMContentLoaded', init);
